def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Strip whitespace and leading $ if present
    s = s.strip()
    if s.startswith("$"):
        s = s[1:]
    # Remove commas
    s = s.replace(",", "")
    if not s:
        raise ValueError("Empty price string")
    try:
        return float(s)
    except ValueError as exc:
        raise ValueError(f"Invalid price format: {s}") from exc

def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    # Convert to set to get distinct values
    unique = set(nums)
    if len(unique) < 2:
        raise ValueError("Need at least two distinct values")
    # Remove the maximum and return the new maximum
    unique.remove(max(unique))
    return max(unique)

